Implement x402 mock facilitator for offline/devnet-unavailable scenarios.

## Purpose
If the x402 devnet facilitator is down, the demo fails. This mock provides a fallback.

## Location Decision
**Mock lives in spyk-sdk only** - the API endpoint in tk-b6y.9 imports from SDK.

## Implementation
```typescript
// spyk-sdk/src/x402/MockX402Facilitator.ts
export interface MockFacilitatorConfig {
  logPayments?: boolean;
  simulateDelay?: number; // ms
}

export class MockX402Facilitator {
  constructor(private config: MockFacilitatorConfig = { logPayments: true }) {}

  async createPaymentProof(invoice: X402Invoice, signer: Keypair): Promise<string> {
    if (this.config.simulateDelay) {
      await new Promise(r => setTimeout(r, this.config.simulateDelay));
    }

    // Generate a mock proof that looks real
    const mockProof = `mock_${Date.now()}_${invoice.amount}_${invoice.recipient.slice(0,8)}`;

    if (this.config.logPayments) {
      console.log('[MOCK X402] Payment proof created:', {
        amount: invoice.amount,
        token: invoice.token,
        recipient: invoice.recipient,
        proof: mockProof
      });
    }

    return mockProof;
  }

  async verifyPayment(proof: string): Promise<{ valid: boolean; details?: any }> {
    // Mock always accepts proofs that start with 'mock_'
    const isValid = proof.startsWith('mock_') || process.env.SPYK_ACCEPT_ALL_PROOFS === 'true';

    if (this.config.logPayments) {
      console.log('[MOCK X402] Payment verification:', { proof, valid: isValid });
    }

    return { 
      valid: isValid,
      details: isValid ? { mock: true, timestamp: Date.now() } : undefined
    };
  }
}
```

## Integration with SpykX402Client
```typescript
// In SpykX402Client constructor or factory
const facilitator = process.env.SPYK_USE_MOCK_FACILITATOR === 'true'
  ? new MockX402Facilitator()
  : new RealX402Facilitator(connection);
```

## Configuration
```bash
SPYK_USE_MOCK_FACILITATOR=true  # Enable mock mode
SPYK_ACCEPT_ALL_PROOFS=true     # Accept any proof (emergency fallback)
```

