Automated smoke test script (shield → pay → verify → receive data).

## Test Location
`spyk-sdk/test/smoke-test.ts` - runs against local spyk-web instance

## Prerequisites
- spyk-web running on localhost:3000
- Devnet wallet with SOL (or mock mode enabled)
- MCP server built and available

## Test Script
```typescript
// spyk-sdk/test/smoke-test.ts
import { SpykPrivacyCash, SpykShadowWire, SpykX402Client } from '../src';
import { Connection, Keypair } from '@solana/web3.js';

const API_URL = process.env.TEST_API_URL || 'http://localhost:3000/api/premium-data';

async function runSmokeTest() {
  console.log('=== SPYK-402 Smoke Test ===\n');

  // Setup
  const connection = new Connection(process.env.SOLANA_RPC || 'https://api.devnet.solana.com');
  const wallet = loadTestWallet();

  const privacyCash = new SpykPrivacyCash(connection, wallet);
  const shadowWire = new SpykShadowWire(connection, wallet);
  const x402Client = new SpykX402Client(privacyCash, shadowWire, connection);

  // Test 1: Check balance
  console.log('1. Checking balance...');
  const balance = await privacyCash.getShieldedBalance();
  console.log(`   Shielded: ${balance} SOL`);

  // Test 2: Shield if needed
  if (balance < 0.01) {
    console.log('2. Shielding funds...');
    const shieldTx = await privacyCash.deposit(0.05);
    console.log(`   Shield tx: ${shieldTx}`);
  } else {
    console.log('2. Balance sufficient, skipping shield');
  }

  // Test 3: Request premium data (expect 402)
  console.log('3. Requesting premium data...');
  const response1 = await fetch(API_URL);
  if (response1.status !== 402) {
    throw new Error(`Expected 402, got ${response1.status}`);
  }
  const invoice = (await response1.json()).x402;
  console.log(`   Got 402 - Amount: ${invoice.amount} ${invoice.token}`);

  // Test 4: Pay privately
  console.log('4. Paying privately...');
  const paymentResult = await x402Client.payPrivately(invoice);
  console.log(`   Payment: ${paymentResult.isPrivate ? 'PRIVATE' : 'public'}`);

  // Test 5: Verify payment with API
  console.log('5. Verifying payment...');
  const verifyResponse = await fetch(API_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ paymentProof: paymentResult.signature })
  });

  // Test 6: Get data
  console.log('6. Fetching data with proof...');
  const response2 = await fetch(API_URL, {
    headers: { 'X-Payment-Proof': paymentResult.signature }
  });

  if (response2.status !== 200) {
    throw new Error(`Expected 200, got ${response2.status}`);
  }

  const data = await response2.json();
  console.log(`   Data received: ${JSON.stringify(data.data).substring(0, 50)}...`);

  console.log('\n✓ Smoke test passed!');
}

function loadTestWallet(): Keypair {
  // Load from env or file
  if (process.env.TEST_PRIVATE_KEY) {
    return Keypair.fromSecretKey(Buffer.from(process.env.TEST_PRIVATE_KEY, 'base64'));
  }
  // Default: use Solana CLI keypair
  const fs = require('fs');
  const keypairFile = process.env.KEYPAIR_PATH || `${process.env.HOME}/.config/solana/id.json`;
  return Keypair.fromSecretKey(Uint8Array.from(JSON.parse(fs.readFileSync(keypairFile, 'utf8'))));
}

runSmokeTest().catch(e => {
  console.error('\n✗ Smoke test failed:', e.message);
  process.exit(1);
});
```

## Running the Test
```bash
# Add to spyk-sdk/package.json scripts:
"test:smoke": "tsx test/smoke-test.ts"

# Run:
cd spyk-sdk
SPYK_USE_MOCK_FACILITATOR=true npm run test:smoke
```

